// Approve pulses these publisher webhooks directly, and a Make webhook aimed at a stopped
// scenario answers 200 and goes nowhere. Background cadence is supposed to keep the webhook
// scenarios live and run the on-demand orchestrators, but it parks aggressively and cannot be
// relied on at the moment a human clicks Approve, which strands the output mid-handoff with a
// status like "Ready for Assets" and no publisher listening. Approval arms its own chain.
const STUDIO_PUBLISH_DISPATCH_SCENARIOS = Object.freeze({
  "AP0": { webhooks: [5612096] },
  "AP0C": { webhooks: STUDIO_AP0C_CHAIN_WEBHOOKS.map((item) => item.id) },
  "FB0": { webhooks: STUDIO_FB0_CHAIN_WEBHOOKS.map((item) => item.id) },
  "AP1-IGS": { webhooks: [5612664, 5845193], orchestrator: STUDIO_IG_ORCH_SCENARIO_ID },
  "AP1-IG": { webhooks: [5862882], orchestrator: STUDIO_IG_ORCH_SCENARIO_ID },
  "FBS3": { webhooks: [STUDIO_FBS3_SCENARIO_ID, STUDIO_FBS4_SCENARIO_ID], orchestrator: 5813561 },
  "YT0": { webhooks: [STUDIO_YT0_SCENARIO_ID, STUDIO_YTP1_SCENARIO_ID, STUDIO_YTS1_SCENARIO_ID, STUDIO_YTS2_SCENARIO_ID, STUDIO_YTS3_SCENARIO_ID] },
  "TTD0": { webhooks: [STUDIO_TTD0_SCENARIO_ID, STUDIO_TTD1_SCENARIO_ID, STUDIO_TTD2_SCENARIO_ID, STUDIO_TTD3_SCENARIO_ID, STUDIO_TTD4_SCENARIO_ID], orchestrator: STUDIO_TTD_ORCH_SCENARIO_ID },
});

async function studioArmPublishScenarios(env, target) {
  const armed = [];
  for (const scenarioId of STUDIO_PUBLISH_DISPATCH_SCENARIOS[target]?.webhooks || []) {
    try {
      await phase6EnsureScenarioActive(env, scenarioId);
      armed.push({ id: scenarioId, ok: true });
    } catch (error) {
      console.warn("publish webhook scenario could not be armed", target, scenarioId, error);
      armed.push({ id: scenarioId, ok: false });
    }
  }
  return armed;
}

// The webhook scenario only stages the platform payload; an on-demand orchestrator carries the
// record the rest of the way, so approval has to run it too or the output stops at the staging step.
const STUDIO_PUBLISH_ORCH_PYTHON = Object.freeze({
  [STUDIO_TTD_ORCH_SCENARIO_ID]: Object.freeze({ stage: "publish_tt", flag: "TTD_ORCH" }),
  [STUDIO_YT_ORCH_SCENARIO_ID]: Object.freeze({ stage: "publish_yt", flag: "YT_ORCH" }),
  [STUDIO_FB_ORCH_SCENARIO_ID]: Object.freeze({ stage: "publish_fb", flag: "FB_ORCH" }),
  [STUDIO_AP_CAR_ORCH_SCENARIO_ID]: Object.freeze({ stage: "publish_ig", flag: "APCAR_ORCH" }),
  [STUDIO_IG_ORCH_SCENARIO_ID]: Object.freeze({ stage: "publish_igrs", flag: "IG_ORCH" }),
});

async function studioRunPublishOrchestrator(env, target) {
  const scenarioId = STUDIO_PUBLISH_DISPATCH_SCENARIOS[target]?.orchestrator;
  if (!scenarioId) return null;
  const orch = STUDIO_PUBLISH_ORCH_PYTHON[scenarioId];
  try {
    if (orch && pipelineStageBackend(env, orch.flag).mode === "python") {
      const { response, payload } = await item4PulsePipelineStage(env, orch.stage, { extra: {} }, orch.flag);
      if (!response.ok) {
        throw new HttpError(
          response.status,
          payload?.message || payload?.error || `Python ${orch.stage} failed (${response.status})`
        );
      }
      return { ok: true, id: scenarioId, backend: "python", payload };
    }
    throw new HttpError(503, `Publish orchestrator ${target} is Python-only.`);
  } catch (error) {
    console.warn("publish orchestrator pulse failed", target, scenarioId, error);
    return { ok: false, id: scenarioId };
  }
}

// Only SAI1 or an explicitly locked user caption may author publishable copy. This
// gate can copy the parent's caption and remove leaked asset inventory, but it must
// never invent a caption from an output title or another production field.
async function studioEnsureOutputCaption(env, record) {
  const existingCaption = String(f(record, "Output_Caption") || "").trim();
  const cleanExistingCaption = item4StripAssetFilenameCaptionText(existingCaption);
  const existingHashtags = String(f(record, "Output_Hashtags") || "").trim();
  if (cleanExistingCaption === existingCaption && existingCaption && existingHashtags) return record;

  const parentId = (f(record, "Content_Item") || [])[0] || null;
  const parent = parentId
    ? await airtableFetch(env, env.AIRTABLE_CONTENT_TABLE_ID, parentId).catch(() => null)
    : null;

  const fields = {};
  const parentCaption = item4StripAssetFilenameCaptionText(f(parent || {}, "Caption"));
  if (cleanExistingCaption !== existingCaption) {
    fields.Output_Caption = cleanExistingCaption || parentCaption || null;
  } else if (!cleanExistingCaption && parentCaption) {
    fields.Output_Caption = parentCaption;
  }

  if (!existingHashtags) {
    const hashtags = String(f(parent || {}, "Hashtags") || "").trim();
    if (hashtags) fields.Output_Hashtags = hashtags;
  }

  if (!Object.keys(fields).length) return record;
  try {
    return await airtableFetch(env, env.AIRTABLE_OUTPUT_TABLE_ID, record.id, {
      method: "PATCH",
      body: JSON.stringify({ fields, typecast: true }),
    });
  } catch (error) {
    console.warn("output caption/hashtag backfill failed", record.id, error);
    return record;
  }
}

// The webhook POST is the only step that actually hands an output to a publisher. Everything
// after it is recoverable on a later pass, so it is split off: this half runs on the request
// path where it cannot be dropped by a cancelled background task or an exhausted invocation.
async function studioDispatchApprovedPublishNow(env, record) {
  if (!studioPublishCanDispatchNow(record)) {
    return {
      ok: true,
      skipped: "scheduled-hold",
      held_until: studioPublishHeldUntilIso(record),
      record,
    };
  }
  record = await studioPromoteDuePublishStatus(env, record);
  record = await studioEnsureOutputCaption(env, record);
  if (!String(f(record, "Output_Caption") || "").trim()) {
    return { ok: false, skipped: "missing-ai-caption", record };
  }
  const plan = studioPublishDispatchTarget(record);
  if (!plan) return { ok: true, skipped: "no-dispatch", record };
  if (plan.graphStory) return { ...await studioPublishFacebookPageStory(env, record), plan, record };
  if (plan.graphFeedPhoto) return { ...await studioPublishInstagramFeedPhoto(env, record), plan, record };
  let ap0 = null;
  if (plan.target !== "AP0C" && plan.target !== "FB0") {
    const ap0Python = pipelineStageBackend(env, "AP0").mode === "python";
    if (!ap0Python) await studioArmPublishScenarios(env, "AP0");
    ap0 = await studioPulseAp0PublicAsset(env, record);
    if (ap0?.ok && !ap0.skipped && ap0.backend !== "python") {
      await new Promise((resolve) => setTimeout(resolve, 8000));
    }
  }
  if (plan.target === "AP1-IG" && pipelineStageBackend(env, "AP1_IG").mode === "python") {
    const pulsed = await studioPulseAp1IgReel(env, record);
    return { ...pulsed, ap0, armed: [], plan, record };
  }
  if (plan.target === "AP1-IGS" && pipelineStageBackend(env, "AP1_IGS").mode === "python") {
    const created = await studioPulseAp1Igs(env, record);
    if (!created.ok || created.skipped || !created.needs_poll) {
      return { ...created, ap0, armed: [], plan, record };
    }
    await new Promise((resolve) => setTimeout(resolve, 8000));
    const polled = await studioPulseAp1IgsPoll(env, record);
    return { ...polled, create: created, ap0, armed: [], plan, record };
  }
  if (plan.target === "FBS3" && pipelineStageBackend(env, "FBS1").mode === "python") {
    const prepared = await studioEnsureFacebookSlideshowAsset(env, record);
    if (!prepared.ok || prepared.still_processing) {
      return { ...prepared, ap0, armed: [], plan, record };
    }
  }
  if (plan.target === "FBS3" && pipelineStageBackend(env, "FBS3").mode === "python") {
    const created = await studioPulseFbs3(env, record);
    if (!created.ok || created.skipped || !created.needs_poll) {
      return { ...created, ap0, armed: [], plan, record };
    }
    await new Promise((resolve) => setTimeout(resolve, 8000));
    const polled = await studioPulseFbs4(env, record);
    return { ...polled, create: created, ap0, armed: [], plan, record };
  }
  if (plan.target === "YT0" && pipelineStageBackend(env, "YT0").mode === "python") {
    const pulsed = await studioEnsureYoutubePublish(env, record);
    return { ...pulsed, ap0, armed: [], plan, record };
  }
  if (plan.target === "TTD0" && pipelineStageBackend(env, "TTD0").mode === "python") {
    const prepared = await studioPulseTtd0(env, record);
    if (!prepared.ok || prepared.skipped || !prepared.needs_init) {
      if (prepared.ok && prepared.skipped) {
        const next = await studioEnsureTiktokDraft(env, record);
        return { ...next, prepare: prepared, ap0, armed: [], plan, record };
      }
      return { ...prepared, ap0, armed: [], plan, record };
    }
    const inited = await studioPulseTtd1(env, record);
    if (!inited.ok || inited.skipped || !inited.needs_poll) {
      return { ...inited, prepare: prepared, ap0, armed: [], plan, record };
    }
    await new Promise((resolve) => setTimeout(resolve, 8000));
    const polled = await studioPulseTtd2(env, record);
    if (!polled.ok || polled.skipped || !polled.needs_email) {
      return { ...polled, init: inited, prepare: prepared, ap0, armed: [], plan, record };
    }
    const emailed = await studioPulseTtd3(env, record);
    return { ...emailed, poll: polled, init: inited, prepare: prepared, ap0, armed: [], plan, record };
  }
  if (plan.target === "FB0" && pipelineStageBackend(env, "FB0").mode === "python") {
    const pulsed = await studioEnsureFacebookPhotoPublish(env, record);
    return { ...pulsed, ap0, armed: [], plan, record };
  }
  if (plan.target === "AP0C" && pipelineStageBackend(env, "AP0C").mode === "python") {
    const pulsed = await studioEnsureInstagramCarouselPublish(env, record);
    return { ...pulsed, ap0, armed: [], plan, record };
  }
  const armed = await studioArmPublishScenarios(env, plan.target);
  const settings = await studioActivePipelineSettings(env, [plan.setting, plan.poll].filter(Boolean));
  const pulsed = await studioPulseMakeWebhook(env, settings[plan.setting], record.id, plan.target, {
    caption: String(f(record, "Output_Caption") || "").trim(),
    hashtags: String(f(record, "Output_Hashtags") || "").trim(),
  });
  return { ...pulsed, ap0, armed, plan, settings, record };
}

async function studioDispatchApprovedPublishTail(env, record, primary) {
  const plan = primary?.plan;
  if (!plan || plan.graphStory || plan.graphFeedPhoto || primary?.backend === "python") return null;
  if (plan.poll) {
    await new Promise((resolve) => setTimeout(resolve, 8000));
    const pollTarget = plan.poll.replace(/_WEBHOOK_URL$/, "").replace(/_/g, "-");
    await studioPulseMakeWebhook(env, primary.settings?.[plan.poll], record.id, pollTarget);
  }
  if (!STUDIO_PUBLISH_DISPATCH_SCENARIOS[plan.target]?.orchestrator) return null;
  // Let the webhook scenario finish staging before the orchestrator looks for its work.
  await new Promise((resolve) => setTimeout(resolve, 10000));
  return studioRunPublishOrchestrator(env, plan.target);
}

function studioPublishDispatchNote(result) {
  if (!result) return "no result";
  if (result.accepted) return `accepted: ${result.target || result.plan?.target || "graph"}`;
  if (result.skipped) return `skipped: ${result.skipped}`;
  const armed = (result.armed || []).map((row) => `${row.id}${row.ok ? "" : "!"}`).join(",");
  return [
    `target=${result.target || result.plan?.target || "?"}`,
    result.ok ? `webhook=ok ${result.status || result.permalink || ""}`.trim() : `webhook=FAILED ${result.status || result.error || ""}`.trim(),
    armed ? `armed=${armed}` : "",
    result.ap0 ? `ap0=${result.ap0.skipped || (result.ap0.ok ? "ok" : "failed")}` : "",
  ].filter(Boolean).join(" | ");
}

// Without a receipt every dispatch failure is invisible: the output looks approved, no publisher
// ran, and nothing on the record says an attempt was ever made. The stamp is also the retry clock
// the reconcile sweep reads, so it has to be written on success and failure alike.
async function studioStampPublishDispatch(env, record, note) {
  const id = String(record?.id || "").trim();
  if (!id) return;
  const count = Number(f(record, "Studio_Publish_Dispatch_Count") || 0) + 1;
  try {
    await airtableFetch(env, env.AIRTABLE_OUTPUT_TABLE_ID, id, {
      method: "PATCH",
      body: JSON.stringify({
        fields: {
          Studio_Publish_Dispatch_At: new Date().toISOString(),
          Studio_Publish_Dispatch_Count: count,
          Studio_Publish_Dispatch_Note: String(note || "").slice(0, 900),
        },
        typecast: true,
      }),
    });
  } catch (error) {
    console.warn("publish dispatch receipt write failed", id, error);
  }
}

async function studioDispatchApprovedPublishAndSchedule(ctx, env, record) {
  if (!studioPublishCanDispatchNow(record)) {
    const heldUntil = studioPublishHeldUntilIso(record);
    await studioStampPublishDispatch(env, record, `held until ${heldUntil || "scheduled time"}`);
    return { ok: true, skipped: "scheduled-hold", held_until: heldUntil, record };
  }
  const plan = studioPublishDispatchTarget(record);
  // Graph stills (Drive → R2 → Instagram) can OOM or abort the isolate. Finish
  // the Approve HTTP response first so Studio/E2E are not killed with the publish.
  if (plan?.graphFeedPhoto && ctx && typeof ctx.waitUntil === "function") {
    ctx.waitUntil((async () => {
      try {
        const primary = await studioDispatchApprovedPublishNow(env, record);
        await studioStampPublishDispatch(env, record, studioPublishDispatchNote(primary));
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        console.warn("studio publish dispatch failed", record?.id, error);
        await studioStampPublishDispatch(env, record, `dispatch failed: ${message}`);
      }
    })());
    return { ok: true, accepted: true, target: plan.target, plan };
  }
  let primary;
  try {
    primary = await studioDispatchApprovedPublishNow(env, record);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.warn("studio publish dispatch failed", record?.id, error);
    await studioStampPublishDispatch(env, record, `dispatch failed: ${message}`);
    return { ok: false, error: message };
  }
  await studioStampPublishDispatch(env, record, studioPublishDispatchNote(primary));
  const tail = studioDispatchApprovedPublishTail(env, record, primary).catch((error) => {
    console.warn("studio publish dispatch tail failed", record?.id, error);
  });
  if (ctx && typeof ctx.waitUntil === "function") ctx.waitUntil(tail);
  return primary;
}

// Redispatching an output whose publisher already started can post it to the platform twice, so
 // most platform statuses are matched against an allowlist of states that mean "no publisher has
 // begun". Instagram carousels are the exception: EnsureInstagramCarouselPublish is stage-gated and
 // safe to re-enter through Parent Ready / Publishing, and parked cadence does not run APCAR orch
 // unless force/startPublish — so due Parent Ready rows must be eligible on this first sweep or
 // they sit past schedule until a later pass still has subrequest budget (304 sat ~3h).
const STUDIO_PUBLISH_RECONCILE_FORMULA = 'AND({Test_Run_ID}=BLANK(),{Do_Not_Publish}=0,{Auto_Publish_Enabled}=1,{Published_At}=BLANK(),'
  + '{Output_Status}="Approved for Publishing",'
  + 'OR({Publish_Status}=BLANK(),{Publish_Status}="Not Ready",{Publish_Status}="Ready",{Publish_Status}="Ready to Schedule",{Publish_Status}="Ready to Publish"),'
  + 'OR({IG_Story_Status}=BLANK(),{IG_Story_Status}="Not Needed",{IG_Story_Status}="Ready"),'
  + 'OR({IG_Carousel_Status}=BLANK(),{IG_Carousel_Status}="Not Selected",{IG_Carousel_Status}="Ready for Asset Prep",{IG_Carousel_Status}="Assets Ready",{IG_Carousel_Status}="Children Processing",{IG_Carousel_Status}="Children Ready",{IG_Carousel_Status}="Parent Processing",{IG_Carousel_Status}="Parent Ready",{IG_Carousel_Status}="Publishing"),'
  + 'OR({TikTok_Draft_Status}=BLANK(),{TikTok_Draft_Status}="Not Selected",{TikTok_Draft_Status}="Ready for Assets",{TikTok_Draft_Status}="Waiting for Schedule"),'
  + 'OR({FB_Slideshow_Status}=BLANK(),{FB_Slideshow_Status}="Not Required",{FB_Slideshow_Status}="Ready to Render"),'
  + 'OR({FB_Publish_Status}=BLANK(),{FB_Publish_Status}="Ready for Assets"),'
  + `${STUDIO_PUBLISH_RECONCILE_SCHEDULE_FORMULA},`
  + 'OR({Studio_Publish_Dispatch_Count}=BLANK(),{Studio_Publish_Dispatch_Count}<8),'
  + 'OR({Studio_Publish_Dispatch_At}=BLANK(),DATETIME_DIFF(NOW(),{Studio_Publish_Dispatch_At},"minutes")>=6))';

async function studioResetYoutubeUploadForRetry(env, record) {
  await airtableFetch(env, env.AIRTABLE_OUTPUT_TABLE_ID, record.id, {
    method: "PATCH",
    body: JSON.stringify({
      fields: {
        YouTube_Stage: "YT1",
        YouTube_Upload_Job_ID: "",
        YouTube_Upload_Status: "Not Started",
        YouTube_Upload_Progress_Percent: 0,
        YouTube_Error_Message: "",
        YouTube_Response_JSON: "",
        Publish_Status: "Ready to Publish",
        Publish_Error_Stage: "",
        Publish_Error_Message: "",
        Publish_Retry_Eligible: true,
        YouTube_Package_Status: "Ready",
        YouTube_Scheduled_Publish_At: null,
      },
      typecast: true,
    }),
  });
}

async function studioHealFailedYoutubeSourceDownloads(env, options = {}) {
  const limit = Number(options.limit || 3);
  const recordId = String(options.recordId || "").trim();
  const formula = recordId
    ? `AND(RECORD_ID()="${recordId}",${YOUTUBE_PRIVATE_SOURCE_HEAL_INNER})`
    : `AND({Test_Run_ID}=BLANK(),{Platform}="YouTube",{Do_Not_Publish}=0,${YOUTUBE_PRIVATE_SOURCE_HEAL_INNER})`;
  let rows = [];
  try {
    rows = await listRecords(env, env.AIRTABLE_OUTPUT_TABLE_ID, { limit, filterFormula: formula });
  } catch (error) {
    console.warn("youtube source-download heal scan failed", error);
    return [];
  }
  const results = [];
  for (const row of rows) {
    if (!studioYoutubeFailedPrivateSource(row)) continue;
    try {
      let publicUrl = studioYoutubePublicSourceUrl(row);
      let stagedVia = publicUrl ? "existing_public_url" : "";
      if (!publicUrl) {
        const staged = await studioStageYoutubePublicMp4FromDrive(env, row);
        if (staged.url) {
          publicUrl = staged.url;
          stagedVia = "worker_drive_mpu";
        } else {
          await airtableFetch(env, env.AIRTABLE_OUTPUT_TABLE_ID, row.id, {
            method: "PATCH",
            body: JSON.stringify({
              fields: {
                Publish_Status: "Ready to Publish",
                Publish_Retry_Eligible: true,
                YouTube_Upload_Job_ID: "",
              },
              typecast: true,
            }),
          }).catch(() => null);
          const ap0 = await studioPulseAp0PublicAsset(env, row);
          const afterAp0 = await airtableFetch(env, env.AIRTABLE_OUTPUT_TABLE_ID, row.id).catch(() => row);
          publicUrl = studioYoutubePublicSourceUrl(afterAp0);
          stagedVia = "ap0";
          if (!publicUrl) {
            results.push({
              id: row.id,
              stage: "ap0",
              ok: ap0?.ok !== false,
              skipped: ap0?.skipped || staged.skip || false,
              healed: "waiting_public_url",
              worker_skip: staged.skip || "",
            });
            continue;
          }
        }
      }
      await studioResetYoutubeUploadForRetry(env, row);
      const refreshed = await airtableFetch(env, env.AIRTABLE_OUTPUT_TABLE_ID, row.id);
      const pulsed = await studioPulseYtRecord(env, "ytp1", "YTP1", refreshed);
      results.push({
        id: row.id,
        stage: "ytp1",
        ok: pulsed?.ok !== false,
        skipped: pulsed?.skipped || false,
        healed: "source-download-401",
        staged_via: stagedVia,
        public_url: publicUrl,
        ytp1: pulsed,
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.warn("youtube source-download heal failed", row.id, error);
      results.push({ id: row.id, stage: "heal", error: message });
    }
  }
  return results;
}


async function studioParkStaleYoutubeQuotaPolls(env, options = {}) {
  const limit = Number(options.limit || 5);
  let rows = [];
  try {
    rows = await listRecords(env, env.AIRTABLE_OUTPUT_TABLE_ID, {
      limit,
      filterFormula: YOUTUBE_STALE_QUOTA_POLL_HEAL_FORMULA,
    });
  } catch (error) {
    console.warn("youtube stale quota-poll park scan failed", error);
    return [];
  }
  const results = [];
  for (const row of rows) {
    try {
      const videoId = String(f(row, "YouTube_Video_ID") || "").trim();
      const stage = String(f(row, "Publish_Error_Stage") || "").trim() || "YTS2_QUOTA";
      const youtubeMessage = String(f(row, "YouTube_Error_Message") || f(row, "Publish_Error_Message") || "").trim();
      const liveQuota = Boolean(videoId)
        && (youtubeLiveQuotaOnly(row.fields || row) || /yts2_quota|yts2_thumbnail|yts2_poll|thumbnail|quota/i.test(stage));
      const errorStage = liveQuota
        ? (/yts2_thumbnail|thumbnail/i.test(stage) ? "YTS2_THUMBNAIL" : "YTS2_QUOTA")
        : /ytp1/i.test(stage) ? "YTP1" : /yts1/i.test(stage) ? "YTS1_QUOTA" : "YTS2_QUOTA";
      const fields = liveQuota
        ? youtubeCoverQuotaParkFields({ errorStage, youtubeMessage })
        : manualPublishRequiredFields({
          errorStage,
          publishMessage: "YouTube API quota exhausted. Manual publish required until the next automatic retry after Pacific midnight.",
          youtubeMessage,
          youtubeStage: videoId ? "YT2" : "YT1",
          uploadStatus: videoId ? "Uploaded" : "Failed",
        });
      await airtableFetch(env, env.AIRTABLE_OUTPUT_TABLE_ID, row.id, {
        method: "PATCH",
        body: JSON.stringify({ fields, typecast: true }),
      });
      results.push({
        id: row.id,
        stage: liveQuota ? "cover_quota_park" : "manual_publish_park",
        error_stage: errorStage,
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.warn("youtube stale quota-poll park failed", row.id, error);
      results.push({ id: row.id, stage: "manual_publish_park", error: message });
    }
  }
  return results;
}


async function healStaleManualFlagsOnPublishedRecord(env, record) {
  const patch = staleManualFlagsOnPublishedFields(record?.fields || record);
  if (!patch) return record;
  try {
    return await airtableFetch(env, env.AIRTABLE_OUTPUT_TABLE_ID, record.id, {
      method: "PATCH",
      body: JSON.stringify({ fields: patch, typecast: true }),
    });
  } catch (error) {
    console.warn("stale manual flags on published heal failed", record?.id, error);
    return record;
  }
}

async function healYoutubeManualWithLiveVideoRecord(env, record, options = {}) {
  const candidate = youtubeManualLiveVideoHealCandidate(record?.fields || record);
  if (!candidate) return record;
  const oembed = youtubeOembedUrl(candidate.liveUrl);
  if (!oembed) return record;
  try {
    const probe = await fetch(oembed, { method: "GET", redirect: "follow" });
    if (!probe.ok) return record;
    return await patchYoutubeManualClose(env, record, {
      url: candidate.liveUrl,
      autoHealed: options.autoHealed !== false,
    });
  } catch (error) {
    console.warn("youtube manual live-video heal failed", record?.id, error);
    return record;
  }
}

async function studioCloseYoutubeManualWithLiveVideo(env, options = {}) {
  const limit = Number(options.limit || 3);
  let rows = [];
  try {
    rows = await listRecords(env, env.AIRTABLE_OUTPUT_TABLE_ID, {
      limit,
      filterFormula: YOUTUBE_MANUAL_LIVE_VIDEO_HEAL_FORMULA,
    });
  } catch (error) {
    console.warn("youtube manual live-video heal scan failed", error);
    return [];
  }
  const results = [];
  for (const row of rows) {
    try {
      const healed = await healYoutubeManualWithLiveVideoRecord(env, row, { autoHealed: true });
      if (healed?.id === row.id && String(f(healed, "Publish_Status") || "").toLowerCase().includes("published")) {
        results.push({
          id: row.id,
          stage: "manual_live_video_heal",
          video_id: youtubeLiveVideoIdFromFields(row.fields || {}),
          ok: true,
        });
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.warn("youtube manual live-video heal failed", row.id, error);
      results.push({ id: row.id, stage: "manual_live_video_heal", error: message });
    }
  }
  return results;
}

async function studioRearmDueYoutubeManualPublishes(env, options = {}) {
  const limit = Number(options.limit || 3);
  const formula = 'AND({Test_Run_ID}=BLANK(),{Platform}="YouTube",{Do_Not_Publish}=0,{Publish_Status}="Manual Publish Required",{Publish_Retry_Eligible}=1,{YouTube_Video_ID}="",OR({Publish_Next_Retry_At}=BLANK(),IS_BEFORE({Publish_Next_Retry_At},NOW())))';
  let rows = [];
  try {
    rows = await listRecords(env, env.AIRTABLE_OUTPUT_TABLE_ID, { limit, filterFormula: formula });
  } catch (error) {
    console.warn("youtube manual-publish rearm scan failed", error);
    return [];
  }
  const results = [];
  for (const row of rows) {
    try {
      const fields = {
        Publish_Status: "Ready to Publish",
        Publish_Error_Stage: "",
        Publish_Error_Message: "",
        YouTube_Error_Message: "",
        YouTube_Response_JSON: "",
        Publish_Next_Retry_At: null,
        Publish_Retry_Eligible: true,
        Manual_Fallback_Required: false,
        Manual_Completion_Status: "Not Required",
        YouTube_Upload_Status: "Not Started",
        YouTube_Stage: "YT1",
        YouTube_Upload_Job_ID: "",
        YouTube_Package_Status: "Ready",
      };
      await airtableFetch(env, env.AIRTABLE_OUTPUT_TABLE_ID, row.id, {
        method: "PATCH",
        body: JSON.stringify({ fields, typecast: true }),
      });
      const refreshed = await airtableFetch(env, env.AIRTABLE_OUTPUT_TABLE_ID, row.id);
      const stage = "ytp1";
      const target = "YTP1";
      const pulsed = await studioPulseYtRecord(env, stage, target, refreshed);
      results.push({
        id: row.id,
        stage: "manual_publish_rearm",
        next: stage,
        ok: pulsed?.ok !== false,
        skipped: pulsed?.skipped || false,
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.warn("youtube manual-publish rearm failed", row.id, error);
      results.push({ id: row.id, stage: "manual_publish_rearm", error: message });
    }
  }
  return results;
}


async function studioReconcileYoutubePublishes(env, options = {}) {
  if (pipelineStageBackend(env, "YT0").mode !== "python") return [];
  const limit = Number(options.limit || 3);
  const results = [];
  try {
    results.push(...await studioHealFailedYoutubeSourceDownloads(env, { limit }));
  } catch (error) {
    console.warn("youtube source-download heal failed", error);
  }
  try {
    results.push(...await studioParkStaleYoutubeQuotaPolls(env, { limit }));
  } catch (error) {
    console.warn("youtube stale quota-poll park failed", error);
  }
  try {
    results.push(...await studioCloseYoutubeManualWithLiveVideo(env, { limit }));
  } catch (error) {
    console.warn("youtube manual live-video heal failed", error);
  }
  try {
    results.push(...await studioRearmDueYoutubeManualPublishes(env, { limit }));
  } catch (error) {
    console.warn("youtube manual-publish rearm failed", error);
  }
  const scans = [
    {
      stage: "yt0",
      target: "YT0",
      formula: 'AND({Test_Run_ID}=BLANK(),{Platform}="YouTube",{Auto_Publish_Enabled}=1,{Do_Not_Publish}=0,{YouTube_Video_ID}="",{Platform_Post_ID}="",OR({Scheduled_Post_Date}=BLANK(),IS_BEFORE({Scheduled_Post_Date},NOW()),{YouTube_Scheduled_Publish_At}!=""),OR({YouTube_Stage}="",{YouTube_Stage}="YT0",AND({Publish_Retry_Eligible}=1,FIND("YT0",UPPER({Publish_Error_Stage}&""))>0)),OR({Publish_Next_Retry_At}=BLANK(),IS_BEFORE({Publish_Next_Retry_At},NOW())))',
    },
    {
      stage: "ytp1",
      target: "YTP1",
      formula: 'AND({Test_Run_ID}=BLANK(),{Platform}="YouTube",{Do_Not_Publish}=0,{YouTube_Stage}="YT1",{YouTube_Upload_Job_ID}="",{YouTube_Video_ID}="",OR({Publish_Status}!="Manual Publish Required",AND({Publish_Retry_Eligible}=1,OR({Publish_Next_Retry_At}=BLANK(),IS_BEFORE({Publish_Next_Retry_At},NOW())))),OR({Publish_Next_Retry_At}=BLANK(),IS_BEFORE({Publish_Next_Retry_At},NOW())))',
    },
    {
      stage: "yts1",
      target: "YTS1",
      formula: 'AND({Test_Run_ID}=BLANK(),{Do_Not_Publish}=0,{YouTube_Stage}="YT2",{YouTube_Upload_Job_ID}!="",{YouTube_Video_ID}="",OR({Publish_Next_Retry_At}=BLANK(),IS_BEFORE({Publish_Next_Retry_At},NOW())))',
    },
    {
      stage: "yts2",
      target: "YTS2",
      formula: 'AND({Test_Run_ID}=BLANK(),{Do_Not_Publish}=0,{YouTube_Stage}="YT2",{YouTube_Video_ID}!="",OR({Publish_Status}!="Manual Publish Required",AND({Publish_Retry_Eligible}=1,OR({Publish_Next_Retry_At}=BLANK(),IS_BEFORE({Publish_Next_Retry_At},NOW())))),OR({Publish_Next_Retry_At}=BLANK(),IS_BEFORE({Publish_Next_Retry_At},NOW())))',
    },
    {
      stage: "yts3",
      target: "YTS3",
      formula: 'AND({Test_Run_ID}=BLANK(),{Do_Not_Publish}=0,{YouTube_Stage}="YT4",{YouTube_Video_ID}!="",{YouTube_Processing_Status}="Succeeded",OR({Publish_Next_Retry_At}=BLANK(),IS_BEFORE({Publish_Next_Retry_At},NOW())))',
    },
  ];
  for (const scan of scans) {
    let rows = [];
    try {
      rows = await listRecords(env, env.AIRTABLE_OUTPUT_TABLE_ID, { limit, filterFormula: scan.formula });
    } catch (error) {
      console.warn(`youtube ${scan.stage} reconcile scan failed`, error);
      continue;
    }
    for (const row of rows) {
      try {
        if (scan.stage === "ytp1" && !studioYoutubePublicSourceUrl(row)) {
          const staged = await studioPulseAp0PublicAsset(env, row);
          results.push({
            id: row.id,
            stage: "ap0",
            ok: staged?.ok !== false,
            skipped: staged?.skipped || false,
            blocked: "missing_public_publish_url",
          });
          continue;
        }
        const pulsed = await studioPulseYtRecord(env, scan.stage, scan.target, row);
        results.push({
          id: row.id,
          stage: scan.stage,
          ok: pulsed?.ok !== false,
          skipped: pulsed?.skipped || false,
          still_processing: pulsed?.still_processing || false,
        });
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        console.warn(`youtube ${scan.stage} reconcile failed`, row.id, error);
        results.push({ id: row.id, stage: scan.stage, error: message });
      }
    }
  }
  return results;
}

async function studioReconcileTiktokDrafts(env, options = {}) {
  if (pipelineStageBackend(env, "TTD0").mode !== "python") return [];
  const limit = Number(options.limit || 3);
  const results = [];
  const scans = [
    {
      stage: "ttd0",
      pulse: studioPulseTtd0,
      formula: `AND({Test_Run_ID}=BLANK(),{Platform}="TikTok",{Do_Not_Publish}=0,{Auto_Publish_Enabled}=1,{TikTok_Draft_Publish_ID}="",${STUDIO_TIKTOK_INBOX_DUE_FORMULA},OR({TikTok_Draft_Status}="Ready for Assets",AND({TikTok_Draft_Status}="Retry Pending",FIND("TTD0",UPPER({Publish_Error_Stage}&""))>0)))`,
      sortField: "Scheduled_Post_Date",
      sortDirection: "asc",
    },
    {
      stage: "ttd1",
      pulse: studioPulseTtd1,
      formula: 'AND({Test_Run_ID}=BLANK(),{Platform}="TikTok",{Do_Not_Publish}=0,{Auto_Publish_Enabled}=1,{TikTok_Draft_Publish_ID}="",OR({TikTok_Draft_Status}="Ready for Delivery",AND({TikTok_Draft_Status}="Retry Pending",OR(FIND("TTD1",UPPER({Publish_Error_Stage}&""))>0,{Publish_Error_Stage}="TTD_CAPACITY"))))',
    },
    {
      stage: "ttd2",
      pulse: studioPulseTtd2,
      formula: 'AND({Test_Run_ID}=BLANK(),{Platform}="TikTok",{Do_Not_Publish}=0,{TikTok_Draft_Publish_ID}!="",OR({TikTok_Draft_Status}="Processing",AND({TikTok_Draft_Status}="Retry Pending",FIND("TTD2",UPPER({Publish_Error_Stage}&""))>0)))',
    },
    {
      stage: "ttd3",
      pulse: studioPulseTtd3,
      formula: 'AND({Test_Run_ID}=BLANK(),{Platform}="TikTok",{Do_Not_Publish}=0,{TikTok_Draft_Delivered_At}!="",{TikTok_Draft_Email_Sent_At}="",{Manual_Completion_Status}="Required",OR({TikTok_Draft_Status}="Draft Delivered — Manual Action Required",{TikTok_Draft_Status}="Manual Completion Received",AND({TikTok_Draft_Status}="Retry Pending",FIND("TTD3",UPPER({Publish_Error_Stage}&""))>0)))',
    },
  ];
  for (const scan of scans) {
    let rows = [];
    try {
      rows = await listRecords(env, env.AIRTABLE_OUTPUT_TABLE_ID, {
        limit,
        filterFormula: scan.formula,
        sortField: scan.sortField || null,
        sortDirection: scan.sortDirection || "desc",
      });
    } catch (error) {
      console.warn(`tiktok ${scan.stage} reconcile scan failed`, error);
      continue;
    }
    for (const row of rows) {
      try {
        let current = row;
        if (scan.stage === "ttd0") current = await studioPromoteDuePublishStatus(env, row);
        const pulsed = await scan.pulse(env, current);
        results.push({ id: current.id, stage: scan.stage, ok: pulsed?.ok !== false, skipped: pulsed?.skipped || false });
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        console.warn(`tiktok ${scan.stage} reconcile failed`, row.id, error);
        results.push({ id: row.id, stage: scan.stage, error: message });
      }
    }
  }
  return results;
}

